const categories = [
  "phone",
  "laptop",
  "computer",
  "gaming",
  "home",
  "gym",
  "accessory",
];

function filterCat(cat) {
  selectedCat = cat;
  render();
}

function render() {
  let q = document.getElementById("search").value.toLowerCase();
  let filtered = products.filter(
    (p) =>
      p.name.toLowerCase().includes(q) &&
      (selectedCat === "all" || p.cat === selectedCat),
  );
  let sectionsHtml = "";
  categories.forEach((cat) => {
    let catProducts = filtered.filter((p) => p.cat === cat);
    if (catProducts.length > 0) {
      sectionsHtml += `<h2 class="section-title">${cat.charAt(0).toUpperCase() + cat.slice(1)}</h2><div class="products">`;
      catProducts.forEach((p, i) => {
        sectionsHtml += `
<div class="card" onclick="openModal(${products.indexOf(p)})">
<img src="${p.img}">
<h3>${p.name}</h3>
<p class="price">$${p.price}</p>
</div>`;
      });
      sectionsHtml += "</div>";
    }
  });
  document.getElementById("sections").innerHTML = sectionsHtml;
}

function openModal(i) {
  let p = products[i];
  document.getElementById("modalContent").innerHTML = `
<img src="${p.img}">
<div>
<h1>${p.name}</h1>
<p>${p.details}</p>
<h2 class="price">$${p.price}</h2>
<button class="btn" onclick="addToCart(${i})">Add to Cart</button>
</div>`;
  document.getElementById("modal").style.display = "flex";
}

function closeModal() {
  document.getElementById("modal").style.display = "none";
}

function addToCart(i) {
  cart.push(products[i]);
  document.getElementById("cartCount").innerText = cart.length;
  closeModal();
}

function openCart() {
  if (cart.length === 0) {
    alert("Cart is empty");
    return;
  }
  let itemsHtml = "";
  cart.forEach((item, i) => {
    itemsHtml += `
<div class="card" style="width:100%;text-align:left;position:relative;" onclick="openModal(${products.indexOf(item)})">
<img src="${item.img}" style="width:100px;float:left;margin-right:15px;">
<div>
<h3>${item.name}</h3>
<p class="price">$${item.price}</p>
</div>
<button class="btn" style="position:absolute;top:15px;right:15px;width:35px;height:35px;" onclick="removeFromCart(${i});event.stopPropagation();">✖</button>
<div style="clear:both;"></div>
</div>`;
  });
  document.getElementById("modalContent").innerHTML = `
<h2>Your Cart</h2>
${itemsHtml}
<h3>Total: $${cart.reduce((sum, p) => sum + p.price, 0)}</h3>
<button class="btn">Checkout</button>`;
  document.getElementById("modal").style.display = "flex";
}

function removeFromCart(i) {
  cart.splice(i, 1);
  document.getElementById("cartCount").innerText = cart.length;
  openCart();
}

function openLogin() {
  document.getElementById("loginModal").style.display = "flex";
}
function closeLogin() {
  document.getElementById("loginModal").style.display = "none";
}

render();
